import { describe, expect, it } from "vitest";

import { createMockMailer } from "../src/mailer";
import { processEnrollmentUpdate } from "../src/notifications";
import { SNAPSHOTS, SUBSCRIPTIONS } from "../src/data";
import { SectionSnapshot, Subscriptions } from "../src/types";

describe("processEnrollmentUpdate", () => {
  it("notifies subscribers when a section transitions from full to open", async () => {
    const mailer = createMockMailer();

    const results = await processEnrollmentUpdate(
      SNAPSHOTS[0],
      SNAPSHOTS[1],
      SUBSCRIPTIONS,
      mailer.sendEmail
    );

    const sentTo = (sectionId: string) =>
      results
        .filter((r) => r.sectionId === sectionId && r.status === "sent")
        .map((r) => r.to)
        .sort();

    expect(sentTo("SEC-A")).toEqual(["alice@berkeley.edu"]);
    expect(sentTo("SEC-B")).toEqual(
      ["bob@berkeley.edu", "carol@berkeley.edu"].sort()
    );
    expect(sentTo("SEC-C")).toEqual(["dave@berkeley.edu"]);

    // SEC-D transitions full -> open too, but has zero subscribers. It must
    // not error and must not produce phantom results.
    expect(results.some((r) => r.sectionId === "SEC-D")).toBe(false);

    // SEC-E was already open before run 0 (never full to begin with) -- this
    // is not a "became open" transition, so its subscriber hears nothing.
    expect(mailer.callLog.some((c) => c.to === "erin@berkeley.edu")).toBe(
      false
    );

    // Exactly alice, bob, carol, dave -- nobody else.
    expect(results).toHaveLength(4);
    expect(mailer.callLog).toHaveLength(4);
  });

  it("does not re-notify while a section remains open on the next run", async () => {
    const mailer = createMockMailer();

    // run 1 -> run 2: SEC-A, SEC-B, SEC-D stay open; SEC-C closes; SEC-E
    // stays open. None of these is a full->open transition, so nobody
    // should be emailed a second time just because the seat is still there.
    const results = await processEnrollmentUpdate(
      SNAPSHOTS[1],
      SNAPSHOTS[2],
      SUBSCRIPTIONS,
      mailer.sendEmail
    );

    expect(results).toHaveLength(0);
    expect(mailer.callLog).toHaveLength(0);
  });

  it("notifies again when a section closes and then genuinely reopens", async () => {
    const mailer = createMockMailer();

    // run 2 -> run 3: SEC-A, SEC-B, SEC-D close (open -> full, no notify).
    // SEC-C closed in run 2 and reopens in run 3 -- a brand new transition,
    // so its subscriber must be notified again even though they were
    // already notified once, back on run 0 -> run 1.
    const results = await processEnrollmentUpdate(
      SNAPSHOTS[2],
      SNAPSHOTS[3],
      SUBSCRIPTIONS,
      mailer.sendEmail
    );

    expect(results).toEqual([
      { sectionId: "SEC-C", to: "dave@berkeley.edu", status: "sent" },
    ]);
    expect(mailer.callLog).toHaveLength(1);
    expect(mailer.callLog[0].to).toBe("dave@berkeley.edu");
  });

  it("handles a failed send gracefully without aborting the rest of the batch", async () => {
    const mailer = createMockMailer();
    mailer.failNextSend();

    const previous: SectionSnapshot[] = [
      { sectionId: "SEC-X", enrolledCount: 20, capacity: 20 },
      { sectionId: "SEC-Y", enrolledCount: 15, capacity: 15 },
    ];
    const current: SectionSnapshot[] = [
      { sectionId: "SEC-X", enrolledCount: 18, capacity: 20 },
      { sectionId: "SEC-Y", enrolledCount: 14, capacity: 15 },
    ];
    const subs: Subscriptions = {
      "SEC-X": ["x@berkeley.edu"],
      "SEC-Y": ["y@berkeley.edu"],
    };

    const results = await processEnrollmentUpdate(
      previous,
      current,
      subs,
      mailer.sendEmail
    );

    // Both transitions should be reflected in the results -- one failed,
    // one sent -- and the failure must not have prevented the other send
    // from being attempted.
    expect(results).toHaveLength(2);

    const failed = results.filter((r) => r.status === "failed");
    const sent = results.filter((r) => r.status === "sent");

    expect(failed).toHaveLength(1);
    expect(sent).toHaveLength(1);
    expect(failed[0].error).toMatch(/simulated smtp failure/i);

    // The one that succeeded actually reached the mailer's call log; the
    // one that failed must not appear there.
    expect(mailer.callLog).toHaveLength(1);
    expect(mailer.callLog[0].to).toBe(sent[0].to);
    expect(mailer.callLog.some((c) => c.to === failed[0].to)).toBe(false);
  });
});
